def _is_path_allowed(self, path: Path) -> bool:
    """Check if path is within scratch_root or explicitly allowed."""
    if self._is_within(path, self._scratch_root):
        return True
    for allowed in self._allowed_paths:
        if self._is_within(path, allowed):
            return True
    return False

