def read_output(self, max_bytes: int = 4096) -> bytes:
    """Read output from PTY, blocking until data available."""
    if self._fd is None:
        raise PTYNotOpen()
    return os.read(self._fd, max_bytes)

def retry_with_delay(func, max_retries: int, delay: float):
    for attempt in range(max_retries):
        try:
            return func()
        except Exception as e:
            if attempt == max_retries - 1:
                raise
            time.sleep(delay)  # Fixed delay, no backoff

def run_hook(self, hook_name: str, context: dict) -> dict:
    hook_path = self._hooks_dir / f"{hook_name}.py"
    if not hook_path.exists():
        return {}
    # Executes hook with full eval process privileges
    spec = importlib.util.spec_from_file_location(hook_name, hook_path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module.run(context)

